/**
 * Registers the precaching service worker (`sw.js`, generated by
 * `scripts/self-host.mjs`) so the viewer keeps working when the connection
 * drops after the first visit.
 *
 * Registration waits until the page has loaded and the browser is idle, so
 * the (large) precache download never competes with the first render.
 * Progress is only reported on `window.__CAD_PRECACHE__` and in the console.
 */
import { IS_OFFLINE_BUILD } from './offline'

export interface CadPrecacheStatus {
  state: 'installing' | 'ready' | 'error'
  version: string
  /** Files in the precache manifest. */
  total: number
  /** Files cached so far. */
  done: number
  totalBytes: number
  bytes: number
  error?: string
}

declare global {
  interface Window {
    /** Latest precache status reported by the service worker. */
    __CAD_PRECACHE__?: CadPrecacheStatus
  }
}

const isPrecacheMessage = (data: unknown): data is CadPrecacheStatus =>
  typeof data === 'object' &&
  data !== null &&
  (data as { type?: unknown }).type === 'cad-precache'

const formatMb = (bytes: number) => `${(bytes / 1024 / 1024).toFixed(1)} MB`

/** Path of this page's entry chunk, which identifies the running build. */
const entryScript = () =>
  document.querySelector<HTMLScriptElement>('script[type="module"][src]')?.src

function onStatus(status: CadPrecacheStatus) {
  const previous = window.__CAD_PRECACHE__
  window.__CAD_PRECACHE__ = status
  if (status.state === previous?.state && status.version === previous.version) {
    return
  }
  if (status.state === 'ready') {
    console.info(
      `[cad-viewer] Available offline: ${status.total} files ` +
        `(${formatMb(status.totalBytes)}) cached.`
    )
  } else if (status.state === 'error') {
    console.warn(`[cad-viewer] Offline cache incomplete: ${status.error}`)
  }
}

/**
 * Lets a waiting (updated) worker take over when this page already runs the
 * build it caches; the worker ignores the request if other pages are open.
 */
function activateIfCurrent(registration: ServiceWorkerRegistration) {
  const entry = entryScript()
  if (registration.waiting && entry) {
    registration.waiting.postMessage({ type: 'cad-precache-activate', entry })
  }
}

async function register() {
  const container = navigator.serviceWorker
  container.addEventListener('message', event => {
    if (isPrecacheMessage(event.data)) onStatus(event.data)
  })
  container.startMessages()

  const registration = await container.register('./sw.js', {
    scope: './',
    updateViaCache: 'none'
  })
  registration.addEventListener('updatefound', () => {
    const worker = registration.installing
    worker?.addEventListener('statechange', () => {
      if (worker.state === 'installed') activateIfCurrent(registration)
    })
  })
  activateIfCurrent(registration)
  const worker =
    registration.installing ?? registration.waiting ?? registration.active
  worker?.postMessage({ type: 'cad-precache-status' })
}

export function registerServiceWorker() {
  if (
    IS_OFFLINE_BUILD ||
    !import.meta.env.PROD ||
    !/^https?:$/.test(window.location.protocol) ||
    !('serviceWorker' in navigator) ||
    !window.isSecureContext
  ) {
    return
  }
  const start = () => {
    const run = () => {
      register().catch(error =>
        console.warn('[cad-viewer] Service worker registration failed', error)
      )
    }
    if ('requestIdleCallback' in window) {
      window.requestIdleCallback(run, { timeout: 5000 })
    } else {
      setTimeout(run, 1000)
    }
  }
  if (document.readyState === 'complete') {
    start()
  } else {
    window.addEventListener('load', start, { once: true })
  }
}
